This error is occurring because the save function for the core/button block is outputting invalid HTML. Specifically, it's outputting:

```html
<div class="wp-block-button has-custom-width wp-block-button__width-[object Object]">...</div> 
```

The `wp-block-button__width-[object Object]` class is invalid, since class names cannot contain spaces or object references.

To fix this, you'll need to update the save function for the core/button block. The save function is located at:

```
/wp-includes/blocks/button/block.json
```

In that file, find the `save` function. It currently looks something like this:

```json
"save": function( props ) { 
	var className = props.className;
	var anchorClass = props.anchorClass;
	var text = props.text;
	var url = props.url;
	var width = props.width;

	className = className ? ' ' + className : ''; 
	anchorClass = anchorClass ? ' ' + anchorClass : '';

	var buttonWidthClass = width ? 'wp-block-button__width-' + width : '';

	return wp.element.createElement(
		'div', 
		{ className: 'wp-block-button' + buttonWidthClass + className },
		wp.element.createElement( 
			'a', 
			{ className: 'wp-block-button__link' + anchorClass, href: url },
			text
		)
	);
}
```

You'll want to update this to properly format the width class name. Change this:

```js
var buttonWidthClass = width ? 'wp-block-button__width-' + width : '';
```

To this:

```js
var buttonWidthClass = width ? 'wp-block-button__width-' + width.replace( /\s/g, '-' ) : '';
```

This will replace any spaces in the width class with dashes, fixing the issue.

Save the block.json file, and the error should disappear and the block will function properly again. Let me know if you have any other questions!

Here's a script to perform visual regression testing on those pages using Playwright and Node.js:

```js
const playwright = require('playwright');
const pixelmatch = require('pixelmatch');
const screenshotDir = 'screenshots';

(async () => {
  const browser = await playwright.chromium.launch();
  const page = await browser.newPage();

  // Capture initial screenshots
  await page.NAME_3('https://2022.artkai.dev/');
  await page.screenshot({ path: `${screenshotDir}/index.png` });
  await page.NAME_3('https://2022.artkai.dev/industries/e-commerce-app-development-services');
  await page.screenshot({ path: `${screenshotDir}/industries.png` });
  // ... Capture other pages ...

  // Run tests
  await page.NAME_3('https://2022.artkai.dev/');
  const indexNewScreenshot = await page.screenshot();
  const indexDiff = await compareScreenshots(
    indexNewScreenshot, 
    `${screenshotDir}/index.png`
  );
  console.log('Index page diff:', indexDiff);

  await page.NAME_3('https://2022.artkai.dev/industries/e-commerce-app-development-services');
  const industriesNewScreenshot = await page.screenshot();
  const industriesDiff = await compareScreenshots(
    industriesNewScreenshot,
    `${screenshotDir}/industries.png` 
  );
  console.log('Industries page diff:', industriesDiff);
  // ... Compare other pages ...

  await browser.close();
})();

async function compareScreenshots(newScreenshot, screenshotFile) {
  const original = await playwright.readFile(screenshotFile);
  const diff = await pixelmatch(original, newScreenshot, null, 500);
  return diff; 
}
```

This script will:

- Launch a Playwright Chromium browser
- Capture initial screenshots of the pages 
- Run the tests by navigating to each page and taking a new screenshot 
- Compare the new screenshots to the originals using the pixelmatch library
- Output the number of different pixels for each page
- Close the browser

You can then visually inspect any pages with differences to confirm if the changes are expected or regressions. Let me know if you have any questions!

