	const { textColor } = attributes;
	const postType = getCurrentPostType()

	if(postType === 'works'){
		return null
	}

	return (
		<Fragment>
			<div>
				<Text>Text color:</Text>
			</div>
			<br/>
			<div>
				<RadioControl
					selected={ textColor }
					options={ [
						{ label: 'Dark', value: 'dark' },
						{ label: 'Light', value: 'light' }
					] }
					onChange={ (value) => setAttributes({ textColor: value }) }
				/>
			</div>
			<br/>
			<br/>
		</Fragment>
	)
}
