        AvgGain += Math.Abs(Prices[j] - Prices[j - 1]);
        AvgLoss += Math.Abs(Prices[j - 1] - Prices[j - 2]);
    }
    double Gain = AvgGain / AvgLoss;
    if (Gain > RSI_High) {
        RSI = 100 - (100 / (1 + Gain));
    } else if (RSI < RSI_Low) {
        RSI = 100 - (100 / (1 - Gain));
    } else {
        RSI = (100 / (1 + Gain)) - (100 / (1 - Gain));
    }
}
```
